SELECT customer_id, event_id, label FROM (SELECT customer_id AS customer_id, event_id AS event_id, label AS label, tick AS tick_ord, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY customer_id ASC NULLS FIRST, tick DESC NULLS LAST, event_id DESC NULLS LAST) AS rn__rank FROM events) t0__ WHERE rn__rank = 1 ORDER BY customer_id ASC NULLS FIRST, tick_ord DESC NULLS LAST, event_id DESC NULLS LAST;
